/**
 * The procedural material texture arrays (facade, ground and interior families): every layer generated by
 * the texture workers (src/workers/tex.worker.ts, src/build/texgen) through the one worker pool,
 * packed into one DataArrayTexture pair per family. Ported from Scale
 * (src/render/TextureLibrary.ts).
 *
 * Scale cached the generated layers in IndexedDB between sessions; that cache is left out here:
 * persistence belongs to src/persist (planned), and the cache comes back through it.
 */
import { DataArrayTexture, LinearFilter, LinearMipmapLinearFilter, NoColorSpace, RGBAFormat, RepeatWrapping, SRGBColorSpace, UnsignedByteType } from 'three/webgpu';
import { FACADE_LAYER_COUNT, FACADE_TILE_METERS, GROUND_LAYER_COUNT, GROUND_TILE_METERS, INTERIOR_LAYER_COUNT, INTERIOR_TILE_METERS, TEX_SIZE } from '../build/texgen';
import type { WorkerPool } from '../workers/pool';
import type { FromTex, TexFamily, ToTex } from '../workers/texProtocol';

export interface MaterialArrays {
  /** rgb = sRGB albedo, a = roughness. */
  albedo: DataArrayTexture;
  /** rg = tangent-space normal xy, b = height, a = ambient occlusion. */
  normal: DataArrayTexture;
  /** Metres covered by one tile of each layer (world UV = metres / tileMeters[layer]). */
  tileMeters: number[];
  layers: number;
}

function makeArray(data: Uint8Array, size: number, layers: number, srgb: boolean): DataArrayTexture {
  const t = new DataArrayTexture(data, size, size, layers);
  t.format = RGBAFormat;
  t.type = UnsignedByteType;
  t.colorSpace = srgb ? SRGBColorSpace : NoColorSpace;
  t.wrapS = t.wrapT = RepeatWrapping;
  t.minFilter = LinearMipmapLinearFilter;
  t.magFilter = LinearFilter;
  t.generateMipmaps = true;
  t.anisotropy = 8;
  t.needsUpdate = true;
  // Only the shaders sample it (facade ≈ 24 MB at 512 px): drop the CPU copy after the upload
  // (Scale's releaseTextureAfterUpload). Never set needsUpdate on it again.
  t.onUpdate = () => {
    (t.image as { data: unknown }).data = null;
    t.onUpdate = null;
  };
  return t;
}

const FAMILIES: Record<TexFamily, { layers: number; tileMeters: number[] }> = {
  facade: { layers: FACADE_LAYER_COUNT, tileMeters: FACADE_TILE_METERS },
  ground: { layers: GROUND_LAYER_COUNT, tileMeters: GROUND_TILE_METERS },
  interior: { layers: INTERIOR_LAYER_COUNT, tileMeters: INTERIOR_TILE_METERS },
};

/**
 * Generate one family's layers through `pool` (a started `WorkerPool<ToTex, FromTex>` of
 * tex.worker.ts), queued in layer order at priority `priority + index`; `onProgress(done, total)`
 * after each layer.
 */
export async function loadTextures(
  pool: WorkerPool<ToTex, FromTex>,
  family: TexFamily,
  onProgress?: (done: number, total: number) => void,
  size = TEX_SIZE,
  priority = 0,
): Promise<MaterialArrays> {
  const { layers, tileMeters } = FAMILIES[family];
  const layerBytes = size * size * 4;
  const albedo = new Uint8Array(layerBytes * layers), normal = new Uint8Array(layerBytes * layers);
  let done = 0;
  const jobs: Promise<void>[] = [];
  for (let index = 0; index < layers; index++) {
    jobs.push(pool.run<Extract<FromTex, { type: 'layer' }>>({ type: 'layer', family, index, size }, priority + index).then((r) => {
      albedo.set(r.albedo, r.index * layerBytes);
      normal.set(r.normal, r.index * layerBytes);
      onProgress?.(++done, layers);
    }));
  }
  await Promise.all(jobs);
  return { albedo: makeArray(albedo, size, layers, true), normal: makeArray(normal, size, layers, false), tileMeters, layers };
}
